#!/usr/bin/env python3
"""Scenario-spec writer for discovered interaction hypotheses (council/tools/interaction_scenarios.py).
Consumes hypotheses from discover_interactions.py; writes sandbox scenario .txt files (meta kind INTERACTION, valid per tools/lint_meta.py)
into council/sandbox/autorun/scenarios/interaction/ . Never pushes to a queue: prints the `queue.js add` commands.
Each plan includes CONSISTENCY variants (late-by-x timing, distance), not only the ideal sequence, and positive/negative controls.
Plugin ops used (all exist in src/Scenario.cs / Realism.cs as of 2026-10-24): setup raw abil souls hardreset give imbueown basemods enemies fetch mark cast hold wait mods cds melee."""
import os, re, json, sys
HERE = os.path.dirname(os.path.abspath(__file__)); COUNCIL = os.path.abspath(os.path.join(HERE, '..'))
SP = os.path.abspath(os.path.join(COUNCIL, '..'))
BUILD_HERO_ENUM = {}   # filled from sandbox/hero_enum.txt
def hero_enum():
    if BUILD_HERO_ENUM: return BUILD_HERO_ENUM
    for ln in open(os.path.join(COUNCIL, 'sandbox', 'hero_enum.txt'), errors='ignore'):
        m = re.match(r'^\s*(\w+)\s*=\s*(\d+)', ln)
        if m: BUILD_HERO_ENUM[m.group(1).lower()] = m.group(1)
    return BUILD_HERO_ENUM
def short(s, n=32):
    s = s.strip()
    return s if len(s) <= n else s[:n].rsplit(' ', 1)[0]
def bits(level): return (1 << level) - 1 if level > 0 else 0
def levels_str(levels): return ';'.join('%d=%d' % (i + 1, l) for i, l in enumerate(levels))

def header(h, kind_line, build, checkpoint, items, levels, mech, question, purpose, hyp_file, extra_meta, why_sel, result_says, player, cond):
    L = ['# interaction test request generated by discover_interactions.py (interaction-discovery-v1) from hypothesis ' + h['id'],
         'meta kind INTERACTION', 'meta question ' + question, 'meta purpose ' + purpose, 'meta mechanics ' + mech,
         'meta expectedstate souls=%d items=%s tiers=%s' % (checkpoint, ','.join(items) or 'none', ' '.join(str(bits(l)) for l in levels)),
         'meta build ' + build, 'meta checkpoint %d' % checkpoint, 'meta items ' + ' '.join(items),
         'meta strategy_source ' + hyp_file, 'meta feeds interaction hypothesis %s (%s)' % (h['id'], h['title'][:80]),
         'meta selection_kind discovery', 'meta selection_reason ' + why_sel, 'meta alternative_reason ' + cond.pop('alternative_reason')]
    for k, v in cond.items(): L.append('meta %s %s' % (k, v))
    for k, v in extra_meta: L.append('meta %s %s' % (k, v))
    for k, v in player.items():
        assert all(len(p.strip()) <= (26 if k == 'player_short' else 32) for p in v.split('|')), (k, v)
        L.append('meta %s %s' % (k, v))
    L.append('meta result_says ' + result_says)
    return L

def reset_block(hero, ebot, levels, souls, gives, imbues, enemies='enemies 1 300 4'):
    L = ['hardreset', 'souls %d' % souls]
    L += ['give ' + g for g in gives]
    L += ['imbueown %s %s' % (i, sl) for i, sl in imbues]
    L += ['basemods', enemies]
    return L

# ------------------------------------------------------------ T2: reset + recast (self recipient only: no allied bot)
def plan_t2(h, I, H, hyp_file, delays=(0.0, 0.6, 1.2)):
    hero_key = h['hero']; hero = hero_enum()[hero_key.replace('hero_', '').lower()] if hero_key.replace('hero_', '').lower() in hero_enum() else None
    ab = next(a for a in H[hero_key]['abilities'] if a['cls'] == h['components'][0]['ability'])
    it = I[next(c['item'] for c in h['components'] if 'item' in c)]
    slot = ab['slot']; levels = [1, 1, 1, 1]; levels[slot - 1] = 4
    sig = 'Signature%d' % slot
    cd = ab['cooldown_by_tier'][3]; dur = ab['duration_by_tier'][3]
    lock = any(e['op'] == 'lockout_target' for e in ab['effects'])
    S = ['setup %s Haze' % hero, 'raw citadel_unlock_flex_slots', 'abil ' + ' '.join(str(bits(l)) for l in levels), 'souls 30000']
    gives = [it['cls']]; imb = [(it['cls'], sig)]
    # P0: positive control: ability cast alone (self) -> modifier present?
    S += reset_block(hero, 'Haze', levels, 30000, gives, imb) + ['mark P0_cast_alone', 'cast %d 0.6' % slot, 'mods', 'wait %.1f' % max(1.0, dur / 2.0), 'mods', 'wait %.1f' % (dur + 1.5), 'mods', 'cds', 'mark none']
    # A: item pressed immediately after first cast (recipient may be locked)
    for d in delays:
        S += reset_block(hero, 'Haze', levels, 30000, gives, imb) + ['mark A_late%.1fs' % d, 'cast %d 0.6' % slot, 'mods', 'wait %.1f' % d, 'cast i1 0.6', 'mods', 'cds', 'cast %d 0.6' % slot, 'mods', 'wait 1.0', 'mods', 'wait %.1f' % (dur + 1.5), 'mods', 'mark none']
    # B: item pressed after the first effect has ended
    S += reset_block(hero, 'Haze', levels, 30000, gives, imb) + ['mark B_after_expiry', 'cast %d 0.6' % slot, 'mods', 'wait %.1f' % (dur + 1.0), 'mods', 'cast i1 0.6', 'cds', 'cast %d 0.6' % slot, 'mods', 'wait 1.0', 'mods', 'wait %.1f' % (dur + 1.5), 'mark none']
    # C: negative control: item pressed BEFORE the first cast (reset wasted) then cast, cast
    S += reset_block(hero, 'Haze', levels, 30000, gives, imb) + ['mark C_item_first', 'cast i1 0.6', 'cast %d 0.6' % slot, 'mods', 'wait 1.0', 'cast %d 0.6' % slot, 'mods', 'wait %.1f' % (dur + 1.5), 'mark none']
    S.append('end')
    mech = 'second cast after the item reset on the imbued ability; recipient is the caster (no allied bot); %s' % ('ability text says the recipient cannot act while affected' if lock else 'no recipient lockout in text')
    meta = header(h, None, build_for(hero_key) or hero_key.replace('hero_', ''), 30000, [it['cls']], levels, mech,
        'Checking whether %s lets %s be cast twice in a row, and what the second cast does.' % (it['name'], ab['name']),
        'decide the UNKNOWN cells of hypothesis %s: item usable while the recipient is affected, refresh vs stack vs rejected, and late-press tolerance' % h['id'],
        hyp_file, [('required_levels', levels_str(levels)), ('levels_mode', 'fixed'),
                   ('required_activation', ' ; '.join(['cast%d|ability|%s|1' % (slot, ab['cls']), 'item|modifier|%s/buff|1' % it['cls']])),
                   ('required_readback', 'items_ok|1|==|1 ; modifier_seen|mods_present|>|0'),
                   ('rotation', '%s at 0s; %s at +late s (late = 0.0/0.6/1.2); %s again; controls: P0 cast alone, B after expiry, C item first' % (ab['name'], it['name'], ab['name'])),
                   ('blocked_by', 'ally recipient branch needs an allied bot; remaining-duration readback missing (mods = names only); self-cast of an ally-target ability unverified')],
        'discovery: data-derived hypothesis %s (item text resets the cooldown of the imbued non-ultimate ability; ability has %ss cooldown, %ss duration at T3; reset-recast and recipient-lockout interplay is UNKNOWN)' % (h['id'], cd, dur),
        'WORKS if the second cast produces a new/extended modifier after the item press; DOES NOT WORK if the item press is rejected or the second cast is refused or adds nothing (compare with controls P0/B/C)',
        dict(player_title=short('%s: cast twice?' % it['name']), player_what=short('%s then %s again' % (it['name'], ab['name'])), player_why=short('Testing a discovered combo'), player_short=short('%s x2 test' % ab['name'], 26), player_expect=short('2nd cast works or not')),
        dict(alternative_reason='controls inside the file: ability alone (P0), item after expiry (B), item before first cast (C); the plain alternative (ordinary single use) is arm P0', cond_scope='ability %d cast + item active, recipient = caster' % slot,
             cond_abilities_used='cast %d twice' % slot, cond_abilities_excluded='all other abilities', cond_accuracy='n/a', cond_misses='none', cond_start_stacks='n/a',
             cond_activations=it['name'], cond_distance='n/a (self recipient)', cond_targets='enemies=1 allies=0'))
    meta += ['readbacks_note_placeholder']
    meta[-1] = 'meta readbacks equipped_items,ability_tiers,activation:%s,ability_cast:%d' % (it['name'], slot)
    return h['id'], meta + S

# ------------------------------------------------------------ T4: cast-phase item lockout (generic: first cheap active item with a modifier)
def plan_t4(h, I, H, hyp_file):
    hero_key = h['hero']; hero = hero_enum()[hero_key.replace('hero_', '').lower()]
    ab = next(a for a in H[hero_key]['abilities'] if a['cls'] == h['components'][0]['ability'])
    cands = sorted([it for it in I.values() if it['active'] and not it['disabled'] and it['tier'] <= 2 and it['cooldown_s'] and it['cooldown_s'] <= 30 and it['imbue'] is None and any(e['evidence'][0]['grade'] != 'TEXT' for e in it['effects'])], key=lambda x: (x['tier'], x['cooldown_s']))
    it = cands[0]
    slot = ab['slot']; levels = [1, 1, 1, 1]; levels[slot - 1] = 4
    S = ['setup %s Haze' % hero, 'raw citadel_unlock_flex_slots', 'abil ' + ' '.join(str(bits(l)) for l in levels), 'souls 30000']
    gives = [it['cls']]
    S += reset_block(hero, 'Haze', levels, 30000, gives, [], 'enemies 1 300 4') + ['fetch 350', 'mark P0_item_alone', 'cast i1 0.6', 'mods', 'cds', 'mark none']
    S += reset_block(hero, 'Haze', levels, 30000, gives, [], 'enemies 1 300 4') + ['fetch 350', 'mark A_item_during_channel', 'cast %d 0.6' % slot, 'mods', 'wait 1.5', 'cast i1 0.6', 'mods', 'cds', 'wait 2.0', 'mods', 'mark none']
    S += reset_block(hero, 'Haze', levels, 30000, gives, [], 'enemies 1 300 4') + ['fetch 350', 'mark B_item_before_channel', 'cast i1 0.6', 'mods', 'cast %d 0.6' % slot, 'mods', 'wait 2.0', 'mods', 'mark none', 'end']
    meta = header(h, None, hero_key.replace('hero_', ''), 30000, [it['cls']], levels, 'state ITEMS_DISABLED in the channel/precast mask of ability %d vs an item active (%s)' % (slot, it['name']),
        'Checking whether %s can be used while %s is channelling.' % (it['name'], ab['name']), 'decide whether the ITEMS_DISABLED cast-phase state blocks item actives and whether an already-running item effect persists',
        hyp_file, [('required_levels', levels_str(levels)), ('levels_mode', 'fixed'), ('required_activation', 'cast%d|ability|%s|1 ; item|modifier|%s/buff|1' % (slot, ab['cls'], it['cls'])),
                   ('required_readback', 'items_ok|1|==|1'), ('rotation', '%s at 0s; item at +1.5 s (inside channel); controls: item alone, item before channel' % ab['name'])],
        'discovery: data-derived hypothesis %s (cast-phase mask lists ITEMS_DISABLED; consequence for item timing)' % h['id'],
        'WORKS (constraint real) if the item press during the channel is rejected while controls P0/B activate; DOES NOT WORK if the item activates during the channel',
        dict(player_title=short('Items during %s?' % ab['name']), player_what=short('Item press while channeling'), player_why=short('Discovered ordering rule'), player_short=short('Item lockout test', 26), player_expect=short('Blocked or not?')),
        dict(alternative_reason='controls: item alone (P0) and item before channel (B)', cond_scope='ability %d channel + item active' % slot, cond_abilities_used='cast %d' % slot, cond_abilities_excluded='all other abilities', cond_accuracy='n/a', cond_misses='none',
             cond_start_stacks='n/a', cond_activations=it['name'], cond_distance='350u', cond_targets='enemies=1 allies=0'))
    meta.append('meta readbacks equipped_items,ability_tiers,activation:%s,ability_cast:%d' % (it['name'], slot))
    return h['id'], meta + S

# ------------------------------------------------------------ T5: ability-delivered heavy melee x item bonus
def plan_t5(h, I, H, hyp_file, dists=(100, 150, 250)):
    hero_key = h['hero']; hero = hero_enum()[hero_key.replace('hero_', '').lower()]
    ab = next(a for a in H[hero_key]['abilities'] if a['cls'] == h['components'][0]['ability'])
    item = next(c['item'] for c in h['components'] if 'item' in c); it = I[item]
    slot = ab['slot']; levels = [1, 1, 1, 1]; levels[slot - 1] = 4
    S = ['setup %s Haze' % hero, 'raw citadel_unlock_flex_slots', 'abil ' + ' '.join(str(bits(l)) for l in levels), 'souls 30000']
    for arm, gives in (('A_without', []), ('B_with', [item]), ('A2_without', []), ('B2_with', [item])):
        for d in dists:
            S += reset_block(hero, 'Haze', levels, 30000, gives, []) + ['fetch %d' % d, 'mark %s_%du' % (arm, d), 'cast %d 0.8' % slot, 'wait 1.5', 'mark none']
    for arm, gives in (('CA_manual_without', []), ('CB_manual_with', [item])):
        S += reset_block(hero, 'Haze', levels, 30000, gives, []) + ['fetch 100', 'mark %s' % arm, 'cast melee 0.8', 'wait 1.0', 'mark none']
    S.append('end')
    meta = header(h, None, hero_key.replace('hero_', ''), 30000, [item], levels, 'ability data flags heavy-melee damage from T%s (%s); item property %s' % (h['components'][0]['tier'], h['components'][0]['src'].split('.')[-1], h['components'][1]['effect']),
        'Checking whether %s boosts the damage of %s.' % (it['name'], ab['name']), 'decide whether an item heavy-melee bonus applies to ability-delivered heavy melee damage (hypothesis %s)' % h['id'],
        hyp_file, [('required_levels', levels_str(levels)), ('levels_mode', 'fixed'), ('required_activation', 'cast%d|ability|%s|1' % (slot, ab['cls'])), ('required_readback', 'items_ok|1|==|1 ; dmg_hits|hits|>|0'),
                   ('rotation', '%s once per block at 3 distances, arms interleaved A,B,A,B; manual melee controls CA/CB prove the item bonus works at all' % ab['name']), ('stack_track', 'none')],
        'discovery: data-derived hypothesis %s (ability text states heavy melee damage; item has a heavy melee bonus property)' % h['id'],
        'WORKS if arm B ability damage exceeds arm A by about the item bonus at every distance; DOES NOT WORK if equal within noise while control CB shows the bonus on manual melee',
        dict(player_title=short('%s boost %s?' % (it['name'], ab['name'])), player_what=short('Item bonus on ability hit'), player_why=short('Testing a discovered link'), player_short=short('Melee bonus test', 26), player_expect=short('More damage with item?')),
        dict(alternative_reason='A = same ability without the item; controls CA/CB = manual melee without/with the item', cond_scope='ability %d cast only (no gun)' % slot, cond_abilities_used='cast %d' % slot, cond_abilities_excluded='gun, other abilities',
             cond_accuracy='n/a', cond_misses='none', cond_start_stacks='n/a', cond_activations='none (passive stat)', cond_distance='100u 150u 250u', cond_targets='enemies=1 allies=0'))
    meta.append('meta readbacks equipped_items,ability_tiers,distance_m,ability_cast:%d' % slot)
    return h['id'], meta + S

PLANS = {'T2': plan_t2, 'T4': plan_t4, 'T5': plan_t5}

def build_for(hero_key):
    """first build id in sandbox/builds_ov.json whose id equals the hero short name (queue.js needs an existing build id)."""
    names = {b['id'] for b in json.load(open(os.path.join(COUNCIL, 'sandbox', 'builds_ov.json')))}
    k = hero_key.replace('hero_', '')
    return k if k in names else None

# ------------------------------------------------------------ T1: spec only (UNTESTABLE-NOW): written to hypotheses/specs/, never to the runnable directory
def plan_t1_spec(h, I, H, hyp_file, offsets=(-3.0, 0.0, 3.0, 6.0, 8.0)):
    hero_key = h['hero']; hero = hero_enum()[hero_key.replace('hero_', '').lower()]
    B = next(a for a in H[hero_key]['abilities'] if a['cls'] == h['components'][0]['ability'])
    A = next(a for a in H[hero_key]['abilities'] if a['cls'] == h['components'][1]['ability'])
    levels = [1, 1, 1, 1]; levels[B['slot'] - 1] = 3; levels[A['slot'] - 1] = 4
    tm = h['timing']; buff = tm.get('cost_buff_duration_s') or 4
    S = ['setup %s Haze' % hero, 'raw citadel_unlock_flex_slots', 'abil ' + ' '.join(str(bits(l)) for l in levels), 'souls 30000']
    for off in offsets:
        S += reset_block(hero, 'Haze', levels, 30000, [], [])
        S += ['# REQUIRES-OP eshoot gun 150   (missing: real enemy damage through the normal damage pipeline; see capability request R1)',
              'mark T1_start_offset%+.1f' % off, 'cast %d 0.6' % B['slot'], '# REQUIRES-OP castself %d   (missing/unverified: self-cast of a friendly-target ability)' % B['slot'],
              'wait %.1f' % max(0.0, buff + off - 1.3), 'cast %d 0.6' % A['slot'], 'wait 12', 'mods', '# REQUIRES-READBACK damage events by victim=player at the crash instant, per tick, and the Hurt-vs-real-damage flag', 'mark none']
    S += reset_block(hero, 'Haze', levels, 30000, [], []) + ['mark CTRL_no_protector', '# REQUIRES-OP eshoot gun 150', 'cast %d 0.6' % B['slot'], 'wait 14', 'mark none']
    S += reset_block(hero, 'Haze', levels, 30000, [], []) + ['mark CTRL_protector_alone', '# REQUIRES-OP eshoot gun 150', 'cast %d 0.6' % A['slot'], 'wait 14', 'mark none']
    S += reset_block(hero, 'Haze', levels, 30000, [], []) + ['mark ARM_interrupt', '# REQUIRES-OP eshoot gun 150', '# REQUIRES-OP ecc stun 1.0   (apply a stun to the player during the protector window)', 'cast %d 0.6' % B['slot'], 'wait %.1f' % max(0.0, buff - 1.3), 'cast %d 0.6' % A['slot'], 'wait 3', 'wait 12', 'mark none', 'end']
    meta = header(h, None, hero_key.replace('hero_', ''), 30000, [], levels, 'delayed/deferred cost of %s vs protection state of %s (see hypothesis %s)' % (B['name'], A['name'], h['id']),
        'Checking whether %s stops what %s defers.' % (A['name'], B['name']), 'decide hypothesis %s: which part of the delayed cost the protector blocks, and the late/early tolerance' % h['id'],
        hyp_file, [('required_levels', levels_str(levels)), ('levels_mode', 'fixed'), ('required_activation', 'cast%d|ability|%s|1 ; cast%d|ability|%s|1' % (B['slot'], B['cls'], A['slot'], A['cls'])),
                   ('required_readback', 'items_ok|1|==|1'), ('rotation', '%s at 0 s; %s at buff end offsets -3 / 0 / +3 / +6 / +8 s; controls and an interrupted arm' % (B['name'], A['name'])),
                   ('blocked_by', 'real_enemy_damage_source; self-cast; apply_cc_to_player (interrupt arm)')],
        'discovery: data-derived hypothesis %s (data points BOTH ways: protector exists, cost modifier carries an ignore-invulnerable flag)' % h['id'],
        'WORKS if total HP lost with the protector covering the delayed cost is clearly below CTRL_no_protector; DOES NOT WORK if equal; PARTIAL if only some ticks/portions change',
        dict(player_title=short('Does %s stop it?' % A['name']), player_what=short('Protector vs delayed cost'), player_why=short('Discovered from game data'), player_short=short('Protector test', 26), player_expect=short('Less damage or same?')),
        dict(alternative_reason='control arms: no protector, protector alone; plain alternative = ordinary healing', cond_scope='ability %d + ability %d, real incoming damage' % (B['slot'], A['slot']), cond_abilities_used='cast %d then %d' % (B['slot'], A['slot']), cond_abilities_excluded='all others',
             cond_accuracy='n/a', cond_misses='none', cond_start_stacks='n/a', cond_activations='%s,%s' % (B['name'], A['name']), cond_distance='350u', cond_targets='enemies=1 allies=0'))
    meta.append('meta readbacks equipped_items,ability_tiers,ability_cast:%d,ability_cast:%d' % (B['slot'], A['slot']))
    return h['id'], meta + S
